from elftools.elf.elffile import ELFFile

with open('libmonosgen-2.0.so.dwarf', 'rb') as f:
    elf = ELFFile(f)

    # Check if DWARF info is available
    if not elf.has_dwarf_info():
        print('No DWARF info')
        exit()

    dwarf = elf.get_dwarf_info()

    addrs = [0x2f4b20, 0x2f4c84]

    for CU in dwarf.iter_CUs():
        line_prog = dwarf.line_program_for_CU(CU)
        if line_prog is None:
            continue

        for entry in line_prog.get_entries():
            if entry.state is None:
                continue
            if entry.state.address in addrs:
                lpe = entry.state
                file_entry = line_prog['file_entry'][lpe.file - 1]
                dir_index = file_entry['dir_index']
                if dir_index > 0:
                    dir_name = line_prog['include_directory'][dir_index - 1]
                else:
                    dir_name = b'.'
                print(f'0x{lpe.address:x}: {dir_name.decode()}/{file_entry.name.decode()}:{lpe.line}')
                addrs.remove(lpe.address)
                if not addrs:
                    break
        if not addrs:
            break

    for a in addrs:
        print(f'0x{a:x}: not found in line program')
" 2>&1

